alter table public.schoolpro_email_queue add column if not exists attempts integer not null default 0,add column if not exists provider_message_id text,add column if not exists last_attempt_at timestamptz;
create index if not exists schoolpro_email_queue_pending_idx on public.schoolpro_email_queue(school_id,status,scheduled_at) where status in('pending','retry');
create or replace function public.retry_schoolpro_email(p_job uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.schoolpro_email_queue;begin select * into j from public.schoolpro_email_queue where id=p_job for update;if j.id is null then raise exception 'Email job not found';end if;if not(public.schoolpro_member_can_manage(j.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=j.school_id and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer'))) then raise exception 'Not authorized';end if;update public.schoolpro_email_queue set status='pending',scheduled_at=now(),error=null where id=j.id;end$$;revoke all on function public.retry_schoolpro_email(uuid) from public,anon;grant execute on function public.retry_schoolpro_email(uuid) to authenticated;